/// or a blank when the child had nothing to report.
fn parse_settle(cell: &str) -> Option<Settle> {
    match cell {
        "not settled" => Some(Settle::Never),
        _ => {
            let mut tokens = cell.split_whitespace();
            let t_s = tokens.next()?.strip_suffix('s')?.parse().ok()?;
