/// The cell's steadiness suffix (` +-0.1%`), empty when the clock was unreadable.
fn rating_suffix(rating: Option<f64>) -> String {
    match rating {
        Some(r) => format!(" +-{:.1}%", r * 100.0),
        None => String::new(),
    }
