462	pub fn settle(
463	    warm: &[ProbeSummary],
464	    clock: &[Option<crate::freq::FreqSample>],
465	    tail_len: usize,
466	) -> Option<Settle> {
467	    if warm.is_empty() || tail_len == 0 || tail_len > warm.len() {
468	        return None;
469	    }
470	    let start_ghz = clock.iter().flatten().next().map(|f| f.khz as f64 / 1e6);
471	    let offset = clock.len().saturating_sub(warm.len());
472	    for start in 0..=(warm.len() - tail_len) {
473	        let clock_suffix = &clock[(offset + start).min(clock.len())..];
474	        if EnvGrade::from_probes(&warm[start..]).is_some_and(|g| g.letter == 'A')
475	            && crate::freq::clock_stable(clock_suffix)
476	        {
477	            let ghz = median_ghz(clock_suffix);
478	            // The clock view when both ends are readable (did the journey ever leave the
479	            // settled state's band), the scan index otherwise (did timing read settled from
480	            // the first probe).
481	            let from_start = match (start_ghz, ghz) {
482	                (Some(s), Some(g)) => (s - g).abs() / g <= crate::freq::FREQ_STABLE_TOL,
483	                _ => start == 0,
