pub fn settle(
    warm: &[ProbeSummary],
    clock: &[Option<crate::freq::FreqSample>],
    tail_len: usize,
) -> Option<Settle> {
    if warm.is_empty() || tail_len == 0 || tail_len > warm.len() {
        return None;
    }
    let start_ghz = clock.iter().flatten().next().map(|f| f.khz as f64 / 1e6);
    let offset = clock.len().saturating_sub(warm.len());
    for start in 0..=(warm.len() - tail_len) {
        let clock_suffix = &clock[(offset + start).min(clock.len())..];
        if EnvGrade::from_probes(&warm[start..]).is_some_and(|g| g.letter == 'A')
            && crate::freq::clock_stable(clock_suffix)
        {
            let ghz = median_ghz(clock_suffix);
            // The clock view when both ends are readable (did the journey ever leave the
            // settled state's band), the scan index otherwise (did timing read settled from
            // the first probe).
            let from_start = match (start_ghz, ghz) {
                (Some(s), Some(g)) => (s - g).abs() / g <= crate::freq::FREQ_STABLE_TOL,
                _ => start == 0,
            };
            return Some(Settle::At {
                t_s: warm[start].t_start_s,
                from_start,
                start_ghz,
                ghz,
                rating: rel_stdev(clock_suffix),
            });
        }
    }
    Some(Settle::Never {
        start_ghz,
        end_ghz: median_ghz(&clock[clock.len().saturating_sub(tail_len)..]),
    })
}

