/// What [`settle`] found: the clock's journey through the warmup stretch, ending either at the
/// earliest suffix that read settled (timing A with the clock held still) or still moving when
/// the stretch ended.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Settle {
    /// The earliest settled suffix: the journey that reached it, when it starts, and how still
    /// the settled state held.
    At {
        /// Seconds from warmup start to the suffix's first probe.
        t_s: f64,
        /// The journey never left the settled state's stability band (clock view), or the scan
        /// succeeded at the first probe (timing-only view): the cell then shows no time and no
        /// arrow, the old `0.01s` here being the first probe's timestamp, a measurement floor
        /// dressed as a duration.
        from_start: bool,
        /// The journey's start: the series' first readable sample (GHz), `None` when the whole
        /// series was unreadable.
        start_ghz: Option<f64>,
        /// The settled state: the suffix's median delivered frequency (GHz), `None` when
        /// unreadable.
        ghz: Option<f64>,
        /// The settled state's steadiness ([`rel_stdev`] of the suffix), `None` when the clock
        /// was unreadable. On a fast exit the suffix is only the exit window, a handful of
        /// samples, so this is indicative rather than a precision instrument.
        rating: Option<f64>,
    },
    /// No suffix down to the exit window read settled: the journey it was still on when the
    /// stretch ended, first readable sample to the exit window's median.
    Never {
        /// The journey's start (GHz), `None` when unreadable.
        start_ghz: Option<f64>,
        /// Where the journey had got to: the exit window's median (GHz), `None` when
        /// unreadable.
        end_ghz: Option<f64>,
    },
}

impl std::fmt::Display for Settle {
    /// The grade block's `settle` cell: the clock's journey, parsed back by
    /// `qualify-environment` (format and parser move together):
    ///
    /// - `3.60->4.09GHz 0.32s +-0.1%`: start, settled state, seconds from warmup start to the
    ///   settled suffix, and the settled state's steadiness
    /// - `4.09GHz from start +-0.1%`: no observed change, so no time and no arrow
    /// - `3.60->4.20GHz not settled`: the journey still under way when warmup gave up
    /// - clock unreadable: the timing-only forms `0.32s`, `from start`, `not settled`
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Settle::At {
                from_start: true,
                ghz: Some(g),
                rating,
                ..
            } => write!(f, "{g:.2}GHz from start{}", rating_suffix(*rating)),
            Settle::At {
                from_start: true,
                ghz: None,
                ..
            } => write!(f, "from start"),
            Settle::At {
                t_s,
                ghz: Some(g),
                start_ghz,
                rating,
                ..
            } => {
                if let Some(s) = start_ghz {
                    write!(f, "{s:.2}->")?;
                }
                write!(f, "{g:.2}GHz {t_s:.2}s{}", rating_suffix(*rating))
            }
            Settle::At { t_s, ghz: None, .. } => write!(f, "{t_s:.2}s"),
            Settle::Never {
                start_ghz: Some(s),
                end_ghz: Some(e),
            } => write!(f, "{s:.2}->{e:.2}GHz not settled"),
            Settle::Never { .. } => write!(f, "not settled"),
        }
    }
}

