/// A warmup row's `settle` cell: the journey forms the harness
/// prints (`3.60->4.09GHz 0.32s +-0.1%`, `3.60->4.20GHz not
/// settled`, and the timing-only `0.32s` / `from start` /
/// `not settled`), or `None` for a blank. Format and parser
/// move together: the child is this same binary.
fn parse_settle(cell: &str) -> Option<Settle> {
    if let Some(head) = cell.strip_suffix("not settled") {
        let (start_ghz, end_ghz) = parse_journey(head.trim_end())?;
        return Some(Settle::Never { start_ghz, end_ghz });
    }
    let (cell, rating) = match cell.rsplit_once(" +-") {
        Some((head, r)) => (
            head,
            Some(r.strip_suffix('%')?.parse::<f64>().ok()? / 100.0),
        ),
        None => (cell, None),
    };
    if cell == "from start" {
        // The timing-only immediate settle: no clock and no meaningful time.
        return Some(Settle::At {
            t_s: 0.0,
            from_start: true,
            start_ghz: None,
            ghz: None,
            rating,
        });
    }
    let (head, time) = match cell.rsplit_once(' ') {
        Some((h, t)) => (h, t),
        None => ("", cell),
    };
    let t_s = time.strip_suffix('s')?.parse().ok()?;
    let (start_ghz, ghz) = parse_journey(head)?;
    Some(Settle::At {
        t_s,
        from_start: false,
        start_ghz,
        ghz,
        rating,
    })
}

/// A cell's journey prefix: `3.60->4.09GHz` -> both ends,
/// `4.09GHz` -> one clock at both ends, empty -> no clock.
/// `None` for anything else.
fn parse_journey(s: &str) -> Option<(Option<f64>, Option<f64>)> {
    if s.is_empty() {
        return Some((None, None));
    }
    let s = s.strip_suffix("GHz")?;
    match s.split_once("->") {
        Some((a, b)) => Some((Some(a.parse().ok()?), Some(b.parse().ok()?))),
        None => {
            let g: f64 = s.parse().ok()?;
            Some((Some(g), Some(g)))
        }
    }
}

/// Parse one grade-block row's cells into a [`Stretch`]. Cell
/// order is the block's column order: grade, phase, settle,
/// worst, spread, bursts, interference, drift, step.
fn parse_stretch(cells: &[&str]) -> Stretch {
