#[test]
fn settle_cell_is_read_but_not_scored() {
    // The timing-only forms.
    assert_eq!(
        parse_settle("0.84s"),
        Some(Settle::At {
            t_s: 0.84,
            from_start: false,
            start_ghz: None,
            ghz: None,
            rating: None
        })
    );
    assert_eq!(
        parse_settle("from start"),
        Some(Settle::At {
            t_s: 0.0,
            from_start: true,
            start_ghz: None,
            ghz: None,
            rating: None
        })
    );
    assert_eq!(
        parse_settle("not settled"),
        Some(Settle::Never {
            start_ghz: None,
            end_ghz: None
        })
    );
    // The journey forms: single spaces stay inside the cell.
    assert_eq!(
        parse_settle("3.60->4.09GHz 0.32s +-0.1%"),
        Some(Settle::At {
            t_s: 0.32,
            from_start: false,
            start_ghz: Some(3.6),
            ghz: Some(4.09),
            rating: Some(0.1 / 100.0)
        })
    );
    assert_eq!(
        parse_settle("4.09->4.09GHz 0.01s +-0.1%"),
        Some(Settle::At {
            t_s: 0.01,
            from_start: false,
            start_ghz: Some(4.09),
            ghz: Some(4.09),
            rating: Some(0.1 / 100.0)
        })
    );
    assert_eq!(
        parse_settle("3.60->4.20GHz not settled"),
        Some(Settle::Never {
            start_ghz: Some(3.6),
            end_ghz: Some(4.2)
        })
    );
    // The bench and run rows carry a blank settle cell.
    assert_eq!(parse_settle("-"), None);
    // A `not settled` warmup still scores from its own worst
    // column, never from the settle cell.
    let never = parse_stretch(&row_cells(
        "  env    warmup  not settled      F    0.30% A       -       0.01% A   9.90% F            0.00% A",
    ));
    assert_eq!(never.letter, 'F');
    assert_eq!(never.drift, Some('F'));
}

