        })
        .collect();
    match settle(&warm, &clock, 4) {
        Some(Settle::At {
            start_ghz,
            ghz,
            rating,
            ..
        }) => {
            assert_eq!(start_ghz, Some(4.09), "the slow core's samples are ignored");
