                if let Some(s) = start_ghz {
                    write!(f, "{s:.2}->")?;
                }
                write!(f, "{g:.2}GHz held {held_s:.2}s{}", rating_suffix(*rating))
            }
            Settle::At {
                held_s, ghz: None, ..
            } => write!(f, "held {held_s:.2}s"),
            Settle::Never {
