/// What [`settle`] found: the clock's journey through the warmup stretch, ending either at the
/// earliest suffix that read settled (timing A with the clock held still) or still moving when
/// the stretch ended.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Settle {
    /// The earliest settled suffix: the journey that reached it, how long the settled state
    /// held, and how still it held.
    At {
        /// Seconds from warmup start to the suffix's first probe: the ramp's end. The record's
        /// `settle_s` and never the cell's, whose time is `held_s`: a box already at speed
        /// reads `t_s` ~0, the first probe's timestamp, a measurement floor that dressed as a
        /// duration confused every reader it met (wink, 2026-08-18).
        t_s: f64,
        /// Seconds the settled state held, the suffix's first probe to the stretch's last: the
        /// cell's time. It agrees with the setup banner's warm budget (a box settled through a
        /// 1.5s warm reads `1.50s`), and `not settled` is its zero.
        held_s: f64,
        /// The journey's start: the series' first readable sample (GHz), `None` when the whole
        /// series was unreadable.
        start_ghz: Option<f64>,
        /// The settled state: the suffix's median delivered frequency (GHz), `None` when
        /// unreadable.
        ghz: Option<f64>,
        /// The settled state's steadiness ([`rel_stdev`] of the suffix), `None` when the clock
        /// was unreadable. On a fast exit the suffix is only the exit window, a handful of
        /// samples, so this is indicative rather than a precision instrument.
        rating: Option<f64>,
    },
    /// No suffix down to the exit window read settled: the journey it was still on when the
    /// stretch ended, first readable sample to the exit window's median.
    Never {
        /// The journey's start (GHz), `None` when unreadable.
        start_ghz: Option<f64>,
        /// Where the journey had got to: the exit window's median (GHz), `None` when
        /// unreadable.
        end_ghz: Option<f64>,
    },
}

impl std::fmt::Display for Settle {
    /// The grade block's `settle` cell: the clock's journey, parsed back by
    /// `qualify-environment` (format and parser move together):
    ///
    /// - `4.84->5.24GHz 0.73s +-0.0%`: start, settled state, how long the settled state held
    ///   before measurement began, and how still it held. A journey that went nowhere still
    ///   prints its arrow (`4.09->4.09GHz`), keeping the column uniform, and a box settled
    ///   through the whole warm reads a hold matching the warm budget
    /// - `3.60->4.20GHz not settled`: the journey still under way when warmup gave up (a hold
    ///   of zero)
    /// - clock unreadable: the timing-only forms `0.73s`, `not settled`
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Settle::At {
                held_s,
                ghz: Some(g),
                start_ghz,
                rating,
                ..
            } => {
                if let Some(s) = start_ghz {
                    write!(f, "{s:.2}->")?;
                }
                write!(f, "{g:.2}GHz {held_s:.2}s{}", rating_suffix(*rating))
            }
            Settle::At {
                held_s, ghz: None, ..
            } => write!(f, "{held_s:.2}s"),
            Settle::Never {
                start_ghz: Some(s),
                end_ghz: Some(e),
            } => write!(f, "{s:.2}->{e:.2}GHz not settled"),
            Settle::Never { .. } => write!(f, "not settled"),
        }
    }
}

