input.old_string:
/// A warmup row's `settle` cell: the journey forms the harness
/// prints (`4.84->5.24GHz 0.73s +-0.0%`, `3.60->4.20GHz not
/// settled`, and the timing-only `0.73s` / `not settled`), or
/// `None` for a blank. Format and parser move together: the
/// child is this same binary. The cell's time is the settled
/// hold, and the ramp-end `t_s` never reaches it, so a parsed
/// `At` carries `t_s` as zero.
fn parse_settle(cell: &str) -> Option<Settle> {
    if let Some(head) = cell.strip_suffix("not settled") {
        let (start_ghz, end_ghz) = parse_journey(head.trim_end())?;
        return Some(Settle::Never { start_ghz, end_ghz });
    }
    let (cell, rating) = match cell.rsplit_once(" +-") {
        Some((head, r)) => (
            head,
            Some(r.strip_suffix('%')?.parse::<f64>().ok()? / 100.0),
        ),
        None => (cell, None),
    };
    let (head, held) = match cell.rsplit_once(' ') {
        Some((h, t)) => (h, t),
        None => ("", cell),
    };
    let held_s = held.strip_suffix('s')?.parse().ok()?;
    let (start_ghz, ghz) = parse_journey(head)?;
    Some(Settle::At {
        t_s: 0.0,
        held_s,
        start_ghz,
        ghz,
        rating,
    })
}

