/// The settle scan's clock gate over the dominant-CPU series: the readable samples' range
/// inside [`crate::freq::FREQ_STABLE_TOL`], skipping the gaps. `clock_stable`'s
/// missing-sample fallback is wrong here: post-filter a `None` means the thread was sampled
/// on another core at that probe, and the readable samples still form an honest same-core
/// series. Bailing on the gaps disabled the gate for every unpinned run, measured as a
/// `+-7.0%` rating inside a 1% gate (2026-08-18). No readable samples still passes, which is
/// the timing-only fallback.
fn filtered_clock_stable(clock: &[Option<crate::freq::FreqSample>]) -> bool {
    let mut min = u64::MAX;
    let mut max = 0u64;
    for f in clock.iter().flatten() {
        min = min.min(f.khz);
        max = max.max(f.khz);
    }
    if max == 0 {
        return true;
    }
    (max - min) as f64 / max as f64 <= crate::freq::FREQ_STABLE_TOL
}

